import re
import zlib

PATH = "report.pdf"


def find_last_startxref(data):
    idx = data.rfind(b"startxref")
    if idx < 0:
        return None
    m = re.search(rb"startxref\s+(\d+)", data[idx:])
    if not m:
        return None
    return int(m.group(1))


def parse_xref_at(data, offset, seen=None):
    """Return (entries, trailer_dict, next_prev)."""
    if seen is None:
        seen = set()
    if offset in seen or offset < 0 or offset >= len(data):
        return {}, {}, None
    seen.add(offset)

    pos = offset
    # Skip whitespace
    while pos < len(data) and data[pos:pos + 1].isspace():
        pos += 1

    if data[pos:pos + 4] == b"xref":
        return parse_classic_xref(data, pos, seen)
    else:
        # Could be an xref stream object
        return parse_xref_stream(data, pos, seen)


def parse_classic_xref(data, pos, seen):
    entries = {}
    trailer = {}
    prev = None
    pos += 4
    while True:
        while pos < len(data) and data[pos:pos + 1].isspace():
            pos += 1
        if data[pos:pos + 7] == b"trailer":
            pos += 7
            while pos < len(data) and data[pos:pos + 1].isspace():
                pos += 1
            trailer, pos = parse_dict(data, pos)
