            em = re.match(rb"(\d{10})\s+(\d{5})\s+([nf])(?:\s|$)", data[pos:pos + 20])
            if not em:
                break
            objnum = start + i
            gen = int(em.group(2))
            kind = em.group(3).decode()
            if kind == "n":
                entries[objnum] = (int(em.group(1)), gen)
            else:
                entries[objnum] = ("free", gen)
            pos += em.end()
