            objnum = start + i
            gen = int(em.group(2))
            kind = em.group(3).decode()
            if kind == "n":
                entries[objnum] = (int(em.group(1)), gen)
            else:
                entries[objnum] = ("free", gen)
            pos += em.end()
    return entries, trailer, prev


def parse_xref_stream(data, pos, seen):
    # Expect "N G obj ... stream ... endstream"
    m = re.match(rb"(\d+)\s+(\d+)\s+obj", data[pos:])
    if not m:
        return {}, {}, None
    objnum = int(m.group(1))
    body_start = m.end()
    endobj = data.find(b"endobj", body_start)
    body = data[body_start:endobj]
    stream_start = body.find(b"stream")
    dict_part = body[:stream_start]
    stream_data = None
    if stream_start >= 0:
        raw_start = stream_start + len(b"stream")
        while raw_start < len(data) and data[raw_start:raw_start + 1].isspace():
            raw_start += 1
        raw_end = data.find(b"endstream", raw_start)
        stream_data = data[raw_start:raw_end]
    d, _ = parse_dict(dict_part, 0)
    trailer = dict(d)
    trailer[b"/XRefStm?"] = None
    # decode stream
    filters = []
    if b"/Filter" in d:
        f = d[b"/Filter"]
        if isinstance(f, list):
            filters = f
        else:
            filters = [f]
    for flt in filters:
        if flt == b"/FlateDecode":
            stream_data = zlib.decompress(stream_data)
        elif flt == b"/ASCIIHexDecode":
            stream_data = bytes.fromhex(
                stream_data.split(b">")[0].replace(b" ", b"").decode()
            )
        else:
            raise ValueError(f"unsupported xref filter {flt!r}")

    W = d.get(b"/W", [1, 4, 2])
    if not isinstance(W, list):
        raise ValueError("bad /W")
    Index = d.get(b"/Index")
    if Index is None:
        Index = [0, d.get(b"/Size", 0)]
    row_len = sum(W)
    entries = {}
    idx = 0
    for i in range(0, len(Index), 2):
        start = Index[i]
        count = Index[i + 1]
        for j in range(count):
            row = stream_data[idx:idx + row_len]
            idx += row_len
            flds = []
            off = 0
            for w in W:
                flds.append(int.from_bytes(row[off:off + w], "big") if w else 0)
                off += w
            typ, f2, f3 = flds
            objnum = start + j
            if typ == 1:
                entries[objnum] = (f2, f3)
            elif typ == 2:
                entries[objnum] = ("stream", f2, f3)
            else:
                entries[objnum] = ("free", 0)
    prev = d.get(b"/Prev")
    return entries, trailer, prev


def parse_dict(data, pos):
    """Parse a PDF dictionary starting at data[pos] == '{'. Returns (dict, endpos)."""
    assert data[pos:pos + 1] == b"<"
    pos += 1
    if data[pos:pos + 1] == b"<":
        pos += 1
    d = {}
    while True:
        while pos < len(data) and data[pos:pos + 1].isspace():
            pos += 1
        if pos >= len(data):
            break
        if data[pos:pos + 1] == b">":
            pos += 1
            if data[pos:pos + 1] == b">":
                pos += 1
            break
        m = re.match(rb"/([^\s/<>\[]+)", data[pos:])
        if not m:
            pos += 1
            continue
        key = b"/" + m.group(1)
        pos = m.end()
        while pos < len(data) and data[pos:pos + 1].isspace():
            pos += 1
        if data[pos:pos + 1] == b"/":
            # name without value -> treat as value True-like
            d[key] = True
            continue
        if data[pos:pos + 1] == b"<":
            val, pos = parse_dict(data, pos)
        elif data[pos:pos + 1] == b"[":
            val, pos = parse_array(data, pos)
        elif data[pos:pos + 1] == b"(":
            val, pos = parse_string(data, pos)
        else:
            m2 = re.match(rb"[^\s/<>\[]+", data[pos:])
            if not m2:
                pos += 1
                continue
            tok = m2.group(0)
            pos = m2.end()
            if re.fullmatch(rb"\d+ 0 R", tok):
                val = tok
            else:
                val = tok
        d[key] = val
    return d, pos


def parse_array(data, pos):
    assert data[pos:pos + 1] == b"["
    pos += 1
    arr = []
    while True:
        while pos < len(data) and data[pos:pos + 1].isspace():
            pos += 1
        if pos >= len(data):
            break
        if data[pos:pos + 1] == b"]":
            pos += 1
            break
        if data[pos:pos + 1] == b"<":
            val, pos = parse_dict(data, pos)
        elif data[pos:pos + 1] == b"[":
            val, pos = parse_array(data, pos)
        elif data[pos:pos + 1] == b"(":
            val, pos = parse_string(data, pos)
        else:
            m2 = re.match(rb"[^\s/<>\[]+", data[pos:])
            if not m2:
                pos += 1
                continue
            tok = m2.group(0)
            pos = m2.end()
            if re.fullmatch(rb"\d+ 0 R", tok):
                val = tok
            else:
                val = tok
        arr.append(val)
    return arr, pos


def parse_string(data, pos):
    depth = 1
    pos += 1
    start = pos
    while pos < len(data) and depth:
        c = data[pos]
        if c == 0x5C:  # backslash escape
            pos += 2
            continue
        if c == 0x28:
            depth += 1
        elif c == 0x29:
            depth -= 1
            if depth == 0:
                break
        pos += 1
    return data[start:pos], pos + 1


def read_object(data, objnum, gen, offset):
    pos = offset
    while pos < len(data) and data[pos:pos + 1].isspace():
        pos += 1
    m = re.match(rb"(\d+)\s+(\d+)\s+obj", data[pos:])
    if not m:
        return None
    body_start = m.end()
    endobj = data.find(b"endobj", body_start)
    if endobj < 0:
        return None
    body = data[body_start:endobj]
    stream_start = body.find(b"stream")
    if stream_start >= 0:
        return body[:stream_start], True
    return body, False


def main():
    with open(PATH, "rb") as f:
        data = f.read()
    print(f"File size: {len(data)} bytes")
    print(f"Header: {data[:16]!r}")
    xref_off = find_last_startxref(data)
    print(f"startxref offset: {xref_off}")

    entries = {}
    trailer = {}
    offset = xref_off
    for _ in range(10):
        e, t, prev = parse_xref_at(data, offset)
        entries.update(e)
        trailer.update(t)
        if prev is None:
            break
        offset = prev
    print(f"Xref entries: {len(entries)}")
    print(f"Trailer keys: {sorted(trailer.keys())}")
    print(f"Encrypted: {b'/Encrypt' in trailer}")
    print(f"Root: {trailer.get(b'/Root')}")
    print(f"Size: {trailer.get(b'/Size')}")

    root_ref = trailer.get(b"/Root")
    if isinstance(root_ref, bytes) and re.fullmatch(rb"\d+ 0 R", root_ref):
        root_num = int(root_ref.split(b" ")[0])
        gen = int(root_ref.split(b" ")[1])
        info = entries.get(root_num)
        if info and info != "free" and not isinstance(info, tuple) or isinstance(info, tuple) and info and info[0] != "free":
            pass
        if isinstance(info, tuple):
            body, has_stream = read_object(data, root_num, gen, info[0])
            if body:
                d, _ = parse_dict(body, 0)
                print(f"Catalog keys: {sorted(d.keys())}")
                print(f"Catalog /Pages: {d.get(b'/Pages')}")
                pages_ref = d.get(b"/Pages")
                if isinstance(pages_ref, bytes):
                    pnum = int(pages_ref.split(b" ")[0])
                    pinfo = entries.get(pnum)
                    if isinstance(pinfo, tuple):
                        pbody, _ = read_object(data, pnum, pinfo[1], pinfo[0])
                        pd, _ = parse_dict(pbody, 0)
                        print(f"Root Pages /Count: {pd.get(b'/Count')}")
                        print(f"Root Pages /Kids count: {len(pd.get(b'/Kids', []))}")
        # check for object streams in use
    n_streams = 0
    n_stream_objs = 0
    for objnum, info in entries.items():
        if isinstance(info, tuple) and info[0] == "stream":
            n_stream_objs += 1
        elif isinstance(info, tuple):
            body, has_stream = read_object(data, objnum, info[1], info[0])
            if has_stream:
                n_streams += 1
    print(f"Objects stored in object streams: {n_stream_objs}")
    print(f"Objects with streams (compressed or not): {n_streams}")


if __name__ == "__main__":
    main()
